21	        this.id = Objects.requireNonNull(id, "id");
22	        this.bookId = Objects.requireNonNull(bookId, "bookId");
23	        this.memberId = Objects.requireNonNull(memberId, "memberId");
24	        this.loanedAt = Objects.requireNonNull(loanedAt, "loanedAt");
25	        this.dueAt = Objects.requireNonNull(dueAt, "dueAt");
26	        if (dueAt.isBefore(loanedAt)) {
27	            throw new IllegalArgumentException("dueAt must not be before loanedAt");
28	        }
29	        this.returnedAt = returnedAt;
30	    }
31	
32	    public static Loan start(UUID bookId, UUID memberId, LocalDate loanedAt) {
33	        return new Loan(UUID.randomUUID(), bookId, memberId, loanedAt, loanedAt.plusDays(LOAN_PERIOD_DAYS), null);
34	    }
35	
36	    public static Loan reconstitute(UUID id, UUID bookId, UUID memberId, LocalDate loanedAt, LocalDate dueAt,
37	                                    LocalDate returnedAt) {
38	        return new Loan(id, bookId, memberId, loanedAt, dueAt, returnedAt);
39	    }
40	
41	    public void returnOn(LocalDate returnedAt) {
42	        if (this.returnedAt != null) {
43	            throw new LoanAlreadyReturnedException(id);
44	        }
45	        Objects.requireNonNull(returnedAt, "returnedAt");
46	        if (returnedAt.isBefore(loanedAt)) {
47	            throw new IllegalArgumentException("returnedAt must not be before loanedAt");
48	        }
49	        this.returnedAt = returnedAt;
50	    }
51	
52	    public boolean isOverdue(LocalDate today) {
53	        return today.isAfter(dueAt);
54	    }
55	
56	    public long overdueDays() {
57	        if (returnedAt == null) {
58	            throw new IllegalStateException("loan is not returned yet: " + id);
59	        }
60	        return Math.max(0, ChronoUnit.DAYS.between(dueAt, returnedAt));
61	    }
62	
63	    public long lateFee() {
64	        return overdueDays() * LATE_FEE_PER_DAY;
65	    }
