18	
19	import java.time.LocalDate;
20	import java.util.Objects;
21	
22	@Service
23	@Transactional
24	public class LoanBookService implements LoanBookUseCase {
25	
26	    private final LoadBookPort loadBookPort;
27	    private final SaveBookPort saveBookPort;
28	    private final LoadMemberPort loadMemberPort;
29	    private final LoadLoanPort loadLoanPort;
30	    private final SaveLoanPort saveLoanPort;
31	
32	    public LoanBookService(LoadBookPort loadBookPort, SaveBookPort saveBookPort, LoadMemberPort loadMemberPort,
33	                           LoadLoanPort loadLoanPort, SaveLoanPort saveLoanPort) {
34	        this.loadBookPort = loadBookPort;
35	        this.saveBookPort = saveBookPort;
36	        this.loadMemberPort = loadMemberPort;
37	        this.loadLoanPort = loadLoanPort;
38	        this.saveLoanPort = saveLoanPort;
39	    }
40	
41	    @Override
42	    public Loan loanBook(LoanBookCommand command) {
43	        Book book = loadBookPort.loadBook(command.bookId())
44	                .orElseThrow(() -> new BookNotFoundException(command.bookId()));
45	        Member member = loadMemberPort.loadMember(command.memberId())
46	                .orElseThrow(() -> new MemberNotFoundException(command.memberId()));
47	        if (book.getStatus() == BookStatus.ON_LOAN) {
48	            throw new BookAlreadyOnLoanException(book.getId());
49	        }
50	        member.ensureCanBorrow(loadLoanPort.countActiveLoansByMemberId(member.getId()));
51	        LocalDate loanedAt = Objects.requireNonNullElseGet(command.loanedAt(), LocalDate::now);
52	        Loan loan = Loan.start(book.getId(), member.getId(), loanedAt);
53	        book.setStatus(BookStatus.ON_LOAN);
54	        saveBookPort.saveBook(book);
55	        saveLoanPort.saveLoan(loan);
56	        return loan;
57	    }
58	}
